-- Declared Wakemu random proportions over exact ORIGINAL species pools only.
CREATE TABLE environmental_random_roster_versions (
 policy_version text PRIMARY KEY, policy_contract text NOT NULL CHECK(policy_contract='wakemu.exact-species-random-roster.v1'),
 min_members integer NOT NULL CHECK(min_members>=2),max_members integer NOT NULL CHECK(max_members>=min_members AND max_members<=8),
 max_zone_members integer NOT NULL CHECK(max_zone_members>0),max_zone_groups integer NOT NULL CHECK(max_zone_groups>0),
 source_authority text NOT NULL,source_sha256 text NOT NULL CHECK(length(source_sha256)=64)
);
CREATE TABLE environmental_random_roster_active (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),policy_version text NOT NULL REFERENCES environmental_random_roster_versions,
 enabled boolean NOT NULL DEFAULT false
);
CREATE TABLE environmental_random_native_species (
 monster_reference integer PRIMARY KEY CHECK(monster_reference>0),native_min_level integer NOT NULL CHECK(native_min_level>0),
 native_max_level integer NOT NULL CHECK(native_max_level>=native_min_level),
 catalog_revision text NOT NULL CHECK(length(catalog_revision)=64),monsters_sha256 text NOT NULL CHECK(length(monsters_sha256)=64)
);
CREATE TABLE environmental_random_roster_policies (
 source_key text NOT NULL,scenario_id integer NOT NULL,policy_version text NOT NULL REFERENCES environmental_random_roster_versions,
 native_type integer NOT NULL CHECK(native_type IN(6,7,8)),native_mode text NOT NULL CHECK(native_mode IN('SOLO','COLLABORATIVE','RACE','COMPETITIVE')),group_reference integer NOT NULL CHECK(group_reference>0),
 group_count integer NOT NULL CHECK(group_count>0),nb_group_for_reward integer NOT NULL CHECK(nb_group_for_reward>=0),
 nb_mob_for_reward integer NOT NULL CHECK(nb_mob_for_reward>=0),challenge_level_min integer NOT NULL CHECK(challenge_level_min>=0),
 challenge_level_max integer NOT NULL CHECK(challenge_level_max>=challenge_level_min),duration_ms bigint NOT NULL CHECK(duration_ms>0),
 source_sha256 text NOT NULL CHECK(length(source_sha256)=64),
 PRIMARY KEY(source_key,scenario_id,policy_version),
 FOREIGN KEY(source_key,scenario_id) REFERENCES environmental_native_scenarios(source_key,scenario_id),
 CHECK((native_type=7 AND nb_group_for_reward>0 AND nb_mob_for_reward=0) OR (native_type IN(6,8) AND nb_mob_for_reward>0 AND nb_group_for_reward=0))
);
CREATE TABLE environmental_random_roster_species (
 source_key text NOT NULL,scenario_id integer NOT NULL,policy_version text NOT NULL,
 monster_reference integer NOT NULL REFERENCES environmental_random_native_species,
 PRIMARY KEY(source_key,scenario_id,policy_version,monster_reference),
 FOREIGN KEY(source_key,scenario_id,policy_version) REFERENCES environmental_random_roster_policies
);
CREATE TABLE environmental_random_roster_bindings (
 source_key text NOT NULL,scenario_id integer NOT NULL,policy_version text NOT NULL,map_id integer NOT NULL CHECK(map_id>0),region_id integer NOT NULL CHECK(region_id>0),
 PRIMARY KEY(source_key,scenario_id,policy_version,map_id,region_id),
 FOREIGN KEY(source_key,scenario_id,policy_version) REFERENCES environmental_random_roster_policies
);
CREATE TABLE environmental_random_roster_draws (
 instance_id bigint PRIMARY KEY REFERENCES environmental_event_instances,
 source_key text NOT NULL,scenario_id integer NOT NULL,policy_version text NOT NULL,
 seed_sha256 text NOT NULL CHECK(length(seed_sha256)=64),group_count integer NOT NULL CHECK(group_count>0),
 min_members integer NOT NULL,max_members integer NOT NULL,roster_sha256 text NOT NULL CHECK(length(roster_sha256)=64),
 FOREIGN KEY(source_key,scenario_id,policy_version) REFERENCES environmental_random_roster_policies
);
CREATE TABLE environmental_random_roster_slots (
 instance_id bigint NOT NULL REFERENCES environmental_random_roster_draws,
 group_ordinal integer NOT NULL CHECK(group_ordinal>=0),member_ordinal integer NOT NULL CHECK(member_ordinal BETWEEN 0 AND 7),
 monster_reference integer NOT NULL REFERENCES environmental_random_native_species,native_level integer NOT NULL CHECK(native_level>0),
 PRIMARY KEY(instance_id,group_ordinal,member_ordinal)
);
CREATE FUNCTION environmental_random_roster_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Frozen environmental random roster source/draw is immutable'; END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['environmental_random_roster_versions','environmental_random_native_species','environmental_random_roster_policies',
 'environmental_random_roster_species','environmental_random_roster_bindings','environmental_random_roster_draws','environmental_random_roster_slots'] LOOP
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION environmental_random_roster_immutable()','immutable_'||t,t);
 END LOOP;
END $$;

